const net = require('net');
const { BAD_REQUEST_RESPONSE, routeRequest } = require('./router');
const { BadRequestError, DEFAULT_MAX_REQUEST_LINE_BYTES, parseRequest } = require('./request');

const PORT = process.env.PORT || 8080;

const readMaxRequestLineBytes = () => {
  const configuredValue = process.env.MAX_REQUEST_LINE_BYTES ?? DEFAULT_MAX_REQUEST_LINE_BYTES;
  const maxRequestLineBytes = Number(configuredValue);
  if (!Number.isSafeInteger(maxRequestLineBytes) || maxRequestLineBytes <= 0) {
    throw new Error(`MAX_REQUEST_LINE_BYTES must be a positive integer, got "${configuredValue}"`);
  }
  return maxRequestLineBytes;
};

const MAX_REQUEST_LINE_BYTES = readMaxRequestLineBytes();

const server = net.createServer({ allowHalfOpen: true }, (conn) => {
  let receivedBytes = Buffer.alloc(0);

  const sendResponse = (response) => conn.end(response, 'latin1');

  conn.on('error', () => {});
  conn.on('data', (chunk) => {
    if (conn.writableEnded) return;
    receivedBytes = Buffer.concat([receivedBytes, chunk]);

    const requestLine = findRequestLine(receivedBytes);
    if (requestLine !== null) {
      sendResponse(routeRequestLine(requestLine));
    } else if (receivedBytes.length >= MAX_REQUEST_LINE_BYTES) {
      sendResponse(BAD_REQUEST_RESPONSE);
    }
  });
  conn.on('end', () => {
    if (!conn.writableEnded) sendResponse(BAD_REQUEST_RESPONSE);
  });
});

server.listen(PORT);

const ROOT_TARGET = '/';
const ECHO_TARGET = '/echo';
const USER_POST_TARGET_PATTERN = /^\/users\/([^/]+)\/posts\/([^/]+)$/;

const buildResponse = (status, { headers = [], body = '' } = {}) =>
  [
    `HTTP/1.1 ${status}`,
    ...headers,
    `Content-Length: ${Buffer.byteLength(body, 'latin1')}`,
    'Connection: close',
    '',
    body,
  ].join('\r\n');

const OK_RESPONSE = buildResponse('200 OK');
const BAD_REQUEST_RESPONSE = buildResponse('400 Bad Request');
const NOT_FOUND_RESPONSE = buildResponse('404 Not Found');
const METHOD_NOT_ALLOWED_RESPONSE = buildResponse('405 Method Not Allowed', {
  headers: ['Allow: GET'],
});

const routeRequest = ({ method, path }) => {
  if (path === ECHO_TARGET) {
    return buildResponse('200 OK', {
      headers: ['Content-Type: text/plain'],
      body: `${method} ${path}`,
    });
  }

  const userPostMatch = USER_POST_TARGET_PATTERN.exec(path);
  if (path !== ROOT_TARGET && !userPostMatch) return NOT_FOUND_RESPONSE;
  if (method !== 'GET') return METHOD_NOT_ALLOWED_RESPONSE;
  if (!userPostMatch) return OK_RESPONSE;

  const [, userId, postId] = userPostMatch;
  return buildResponse('200 OK', {
    headers: ['Content-Type: text/plain'],
    body: `${userId} ${postId}`,
  });
};

module.exports = { BAD_REQUEST_RESPONSE, routeRequestLine };

